import subprocess, RNA
# harvest many distinct solutions per shape by repeated inverse_fold
shapes = {
 'big': '(((.(..(.(((...)))..)..)..)))',
 'small': '((....))',
 'med': '(..(....)..)',
}
def solve(t, n=200):
    seqs=set()
    for _ in range(n):
        s, d = RNA.inverse_fold('A'*len(t), t)
        if d==0:
            seqs.add(s)
        if len(seqs)>=8: break
    return seqs
for k,t in shapes.items():
    ss=solve(t)
    print(k, len(t), len(ss))
    for s in list(ss)[:8]:
        print('  ',s)
